using System;using System.Drawing;using System.Globalization;using System.IO;using System.Text;using System.Windows.Forms;using ScoreModern.RecoveredFragments;
namespace ScoreModern {public sealed partial class Editor {
 bool originalGroupFlipQuestion;
 readonly short[] originalGroupFields={1,0,200,0,0};int originalGroupField;InputFieldSpan[] originalGroupSpans;
 readonly SetupValueBox originalGroupValueBox=new SetupValueBox{Visible=false};Font originalGroupValueFont;
 void InitializeOriginalGroupFields(){contextLine.MouseClick+=(s,e)=>Safe(()=>{if(mode!=ScreenMode.EditGroupMenu||groupCommand!=null||originalGroupSpans==null||e.Button!=MouseButtons.Left)return;for(int n=0;n<5;n++)if(InputFieldBounds((NativeTextLabel)contextLine,originalGroupSpans[n]).Contains(e.X,e.Y)){ApplyOriginalGroupField(command.Text);originalGroupField=n;UpdateClassic();OpenOriginalGroupValue();return;}});Disposed+=(s,e)=>{originalGroupValueBox.Dispose();if(originalGroupValueFont!=null)originalGroupValueFont.Dispose();};}
 void ResetOriginalGroupFields(){originalGroupFields[0]=(short)originalNotationStaff;originalGroupFields[1]=0;originalGroupFields[2]=200;originalGroupFields[3]=originalGroupFields[4]=0;originalGroupField=0;command.Clear();}
 void UpdateOriginalGroupContext(){if(mode!=ScreenMode.EditGroupMenu)return;var row=(NativeTextLabel)contextLine;string[] names={"Base Staff","Left Pos","Right Pos","Code Num","Top Staff"};var text=new StringBuilder();var spans=new InputFieldSpan[5];for(int n=0;n<5;n++){if(n>0)text.Append("  ");int start=text.Length;text.Append(names[n]+" = ");int value=text.Length;text.Append(originalGroupFields[n].ToString(CultureInfo.InvariantCulture));spans[n]=new InputFieldSpan{Start=start,ValueStart=value,End=text.Length,Value=originalGroupFields[n].ToString(CultureInfo.InvariantCulture)};}originalGroupSpans=spans;row.Text=text.ToString();row.FitInputRow=true;row.HighlightColor=inputHighlightColor;row.HighlightStart=spans[originalGroupField].Start;row.HighlightLength=groupCommand==null?spans[originalGroupField].End-spans[originalGroupField].Start:0;row.Cursor=groupCommand==null?Cursors.IBeam:Cursors.Default;if(groupCommand==null)Message("GROUP EDIT    Adjust Parameters, then select Function.    Press ESC to Exit");row.Invalidate();}
 void ApplyOriginalGroupField(string text){if(String.IsNullOrWhiteSpace(text))return;var values=LayoutNumbers(text);if(values.Length!=1)throw new InvalidDataException("Enter one Group Edit field value.");long integer;if(!FiniteBinary32Integer64.TryConvert(BitConverter.ToUInt32(BitConverter.GetBytes(values[0]),0),out integer))throw new InvalidDataException("Group Edit value is outside the finite converter range.");short word=unchecked((short)integer);int[] min={1,-99,-99,0,0},max={99,216,218,18,32};if(word<min[originalGroupField]||word>max[originalGroupField])throw new InvalidDataException("This Group Edit field requires "+min[originalGroupField]+" to "+max[originalGroupField]+".");originalGroupFields[originalGroupField]=word;if(originalGroupField==0)originalNotationStaff=word;else if(originalGroupField==1&&word>=originalGroupFields[2])originalGroupFields[2]=(short)(word+3);else if(originalGroupField==2&&word<=originalGroupFields[1])originalGroupFields[1]=(short)(word-3);command.Clear();UpdateClassic();}
 bool SubmitOriginalGroupField(string text){if(mode!=ScreenMode.EditGroupMenu||groupCommand!=null)return false;if(text.Trim()=="/"){originalGroupField=(originalGroupField+1)%5;UpdateClassic();return true;}ApplyOriginalGroupField(text);return true;}
 bool SubmitOriginalGroupFlip(string text){if(!originalGroupFlipQuestion)return false;string answer=text.Trim().ToUpperInvariant();if(answer!=""&&answer!="U"&&answer!="D"&&answer!="N")return true;originalGroupFlipQuestion=false;CommitOriginalFlip(answer=="U"?"FLU":answer=="D"?"FLD":answer=="N"?"FLN":"FLO");UpdateClassic();return true;}
 bool GroupFieldCharacter(KeyPressEventArgs e){if(originalGroupFlipQuestion){if(e.KeyChar=='U'||e.KeyChar=='u'||e.KeyChar=='D'||e.KeyChar=='d'||e.KeyChar=='N'||e.KeyChar=='n'){e.Handled=true;Safe(()=>SubmitOriginalGroupFlip(e.KeyChar.ToString()));return true;}if(!Char.IsControl(e.KeyChar)){e.Handled=true;return true;}}if(mode!=ScreenMode.EditGroupMenu||groupCommand!=null||originalGroupValueBox.Focused)return false;if(e.KeyChar=='/'){e.Handled=true;Safe(()=>{ApplyOriginalGroupField(command.Text);originalGroupField=(originalGroupField+1)%5;UpdateClassic();});return true;}if(!Char.IsControl(e.KeyChar)&&(e.KeyChar<'-'||e.KeyChar>'9')){e.Handled=true;return true;}return false;}
 bool OriginalGroupFieldKey(Keys keys){if(originalGroupFlipQuestion&&keys==Keys.Escape){originalGroupFlipQuestion=false;ClearMainGroup();command.Clear();UpdateClassic();return true;}if(mode!=ScreenMode.EditGroupMenu||groupCommand!=null)return false;Keys key=keys&Keys.KeyCode;if(key>=Keys.F1&&key<=Keys.F8&&(keys&Keys.Modifiers)!=Keys.None&&keys!=(Keys.Alt|Keys.F4))return true;if(originalGroupValueBox.Focused){if(key==Keys.Enter){Safe(()=>{ApplyOriginalGroupField(originalGroupValueBox.Text);CloseOriginalGroupValue();});return true;}if(key==Keys.Escape){CloseOriginalGroupValue();return true;}return false;}if((keys&Keys.Modifiers)==Keys.None&&(key==Keys.Insert||key==Keys.Delete)||keys==(Keys.Control|Keys.Q)||keys==(Keys.Control|Keys.R))return true;if((keys&Keys.Modifiers)==Keys.None&&(key==Keys.Left||key==Keys.Right)){Safe(()=>{ApplyOriginalGroupField(command.Text);originalGroupField=(originalGroupField+(key==Keys.Right?1:4))%5;UpdateClassic();});return true;}return false;}
 void OpenOriginalGroupValue(){var row=(NativeTextLabel)contextLine;var span=originalGroupSpans[originalGroupField];using(var g=row.CreateGraphics()){float cell;var fitted=row.FitInputFont(g,out cell);if(originalGroupValueFont!=null)originalGroupValueFont.Dispose();originalGroupValueFont=fitted;originalGroupValueBox.Font=fitted??row.Font;row.Controls.Add(originalGroupValueBox);var bounds=NativeInterfaceText.TextSpan(g,row.Text,fitted??row.Font,span.ValueStart,span.End-span.ValueStart,row.ClientRectangle);originalGroupValueBox.Bounds=new Rectangle((int)bounds.Left,0,Math.Max(35,(int)bounds.Width+15),row.Height);}originalGroupValueBox.BackColor=inputHighlightColor;originalGroupValueBox.ForeColor=inputHighlightColor.GetBrightness()>.5?Color.Black:Color.White;originalGroupValueBox.Text=originalGroupFields[originalGroupField].ToString(CultureInfo.InvariantCulture);originalGroupValueBox.Show();originalGroupValueBox.BringToFront();originalGroupValueBox.Focus();originalGroupValueBox.SelectAll();}
 void CloseOriginalGroupValue(){originalGroupValueBox.Hide();command.Focus();}
}}
